import { createFileRoute } from "@tanstack/react-router";
import { useEffect, useMemo, useState } from "react";
import {
  AlertCircle,
  ArrowLeft,
  ArrowRight,
  BarChart3,
  Bell,
  Check,
  CheckCircle2,
  ChevronDown,
  CircleHelp,
  ClipboardCheck,
  Code2,
  Copy,
  Download,
  FileText,
  GitBranch,
  Globe2,
  History,
  LayoutDashboard,
  Link2,
  ListFilter,
  Menu,
  MessageSquareText,
  Play,
  Plus,
  Search,
  Settings,
  ShieldCheck,
  Sparkles,
  Target,
  Terminal,
  UserRound,
  X,
  Zap,
} from "lucide-react";

export const Route = createFileRoute("/")({
  head: () => ({
    meta: [
      { title: "AccessLens — Audit the experience, not just the code" },
      { name: "description", content: "Accessibility auditing for rendered websites, user journeys, and developer-ready fixes." },
      { property: "og:title", content: "AccessLens — Audit the experience, not just the code" },
      { property: "og:description", content: "Find detectable accessibility barriers, understand their impact, and ship actionable fixes." },
    ],
  }),
  component: AccessLens,
});

type View = "overview" | "scan" | "issues" | "journeys" | "reports" | "integrations" | "settings";
type Severity = "critical" | "serious" | "moderate";

type Issue = {
  id: number;
  severity: Severity;
  title: string;
  wcag: string;
  category: string;
  page: string;
  selector: string;
  users: string;
  explanation: string;
  fix: string;
};

const issues: Issue[] = [
  { id: 1, severity: "critical", title: "Button has no accessible name", wcag: "4.1.2 Name, Role, Value", category: "ARIA", page: "/checkout", selector: '<button class="icon-btn">', users: "Screen-reader users", explanation: "This interactive button does not expose a meaningful accessible name. A screen reader may announce only “button” without telling someone what action it performs.", fix: '<button class="icon-btn" aria-label="Delete account">\n  <svg aria-hidden="true">...</svg>\n</button>' },
  { id: 2, severity: "critical", title: "Modal does not trap keyboard focus", wcag: "2.4.3 Focus Order", category: "Keyboard", page: "/checkout", selector: "<div role=\"dialog\">", users: "Keyboard-only users", explanation: "When the payment dialog opens, focus remains behind the overlay. Keyboard users can move into the page underneath and lose their place.", fix: "<Dialog onOpenAutoFocus={(event) => event.preventDefault()}>\n  <DialogContent aria-labelledby=\"payment-title\">\n    ...\n  </DialogContent>\n</Dialog>" },
  { id: 3, severity: "critical", title: "Error message is not announced", wcag: "4.1.3 Status Messages", category: "Forms", page: "/login", selector: '<div class="form-error">', users: "Screen-reader users", explanation: "The login error appears visually but is not exposed as a status message, so someone using a screen reader may not know that submission failed.", fix: '<div role="alert" aria-live="assertive">\n  Email or password is incorrect.\n</div>' },
  { id: 4, severity: "serious", title: "Form field is missing a label", wcag: "3.3.2 Labels or Instructions", category: "Forms", page: "/contact", selector: '<input type="email">', users: "Screen-reader users", explanation: "The email input has no programmatically associated label. Users hear an unlabeled field and cannot confirm what information is expected.", fix: '<label htmlFor="email">Email address</label>\n<input id="email" name="email" type="email" />' },
  { id: 5, severity: "serious", title: "Text and background contrast is too low", wcag: "1.4.3 Contrast (Minimum)", category: "Color", page: "/products", selector: ".muted-link", users: "Low-vision users", explanation: "The secondary navigation link renders at a 3.1:1 contrast ratio. Normal text needs at least 4.5:1 for WCAG AA.", fix: ".muted-link {\n  color: #1e5aa8;\n  font-weight: 600;\n}" },
  { id: 6, severity: "serious", title: "Image is missing alternative text", wcag: "1.1.1 Non-text Content", category: "Images", page: "/products/running-shoes", selector: '<img src="shoe.jpg">', users: "Screen-reader users", explanation: "The product image communicates useful context but has no alternative text. The content is unavailable when images cannot be seen.", fix: '<img src="shoe.jpg" alt="Blue trail running shoe with orange sole" />' },
  { id: 7, severity: "serious", title: "Keyboard focus is not visible", wcag: "2.4.7 Focus Visible", category: "Keyboard", page: "/", selector: ".nav-link:focus", users: "Keyboard-only users", explanation: "The focused navigation link has no visible focus indicator, making it difficult to track position while tabbing through the page.", fix: ".nav-link:focus-visible {\n  outline: 3px solid #1e5aa8;\n  outline-offset: 3px;\n}" },
  { id: 8, severity: "serious", title: "Heading hierarchy skips a level", wcag: "1.3.1 Info and Relationships", category: "Structure", page: "/products", selector: "<h1> ... <h3>", users: "Screen-reader users", explanation: "The page jumps from h1 to h3, which makes the content outline harder to understand and navigate by headings.", fix: "<h1>Products</h1>\n<h2>Running shoes</h2>\n<h3>Trail collection</h3>" },
  { id: 9, severity: "moderate", title: "Link purpose is unclear", wcag: "2.4.4 Link Purpose", category: "Navigation", page: "/", selector: '<a href="/more">Read more</a>', users: "Screen-reader users", explanation: "The link text does not identify what content it opens when read out of context.", fix: '<a href="/shipping">Read our shipping policy</a>' },
  { id: 10, severity: "moderate", title: "Page language is not declared", wcag: "3.1.1 Language of Page", category: "Structure", page: "/contact", selector: "<html>", users: "Screen-reader users", explanation: "Without a language declaration, assistive technology may use the wrong pronunciation rules.", fix: '<html lang="en">' },
  { id: 11, severity: "moderate", title: "Decorative icon is exposed", wcag: "1.1.1 Non-text Content", category: "Images", page: "/cart", selector: '<svg class="cart-icon">', users: "Screen-reader users", explanation: "The decorative cart icon is announced twice because it lacks an accessible-hidden attribute.", fix: '<svg aria-hidden="true" focusable="false">...</svg>' },
  { id: 12, severity: "moderate", title: "Required field is not identified", wcag: "3.3.2 Labels or Instructions", category: "Forms", page: "/registration", selector: "<input name=\"name\">", users: "Cognitive and screen-reader users", explanation: "A required field is only indicated by a visual asterisk with no text alternative.", fix: '<label>Full name <span aria-hidden="true">*</span><span className="sr-only">required</span></label>' },
  { id: 13, severity: "moderate", title: "Skip link is missing", wcag: "2.4.1 Bypass Blocks", category: "Navigation", page: "/", selector: "<body>", users: "Keyboard-only users", explanation: "Repeated navigation cannot be bypassed quickly, adding unnecessary keyboard work on every page.", fix: '<a className="skip-link" href="#main">Skip to content</a>' },
  { id: 14, severity: "moderate", title: "Touch target is too small", wcag: "2.5.8 Target Size", category: "Keyboard", page: "/cart", selector: ".quantity-stepper button", users: "Motor-impaired users", explanation: "The quantity controls are smaller than the recommended target size and may be difficult to activate accurately.", fix: ".quantity-stepper button {\n  min-width: 44px;\n  min-height: 44px;\n}" },
  { id: 15, severity: "moderate", title: "Table header is not associated", wcag: "1.3.1 Info and Relationships", category: "Structure", page: "/checkout", selector: "<th>Order total</th>", users: "Screen-reader users", explanation: "The data table header is not associated with its cells, making order details harder to scan non-visually.", fix: '<th scope="col">Order total</th>' },
];

const severityMeta: Record<Severity, { label: string; className: string; dot: string }> = {
  critical: { label: "Critical", className: "bg-critical/10 text-critical", dot: "bg-critical" },
  serious: { label: "Serious", className: "bg-serious/10 text-serious", dot: "bg-serious" },
  moderate: { label: "Moderate", className: "bg-moderate/15 text-moderate", dot: "bg-moderate" },
};

const navItems: { id: View; label: string; icon: typeof LayoutDashboard }[] = [
  { id: "overview", label: "Overview", icon: LayoutDashboard },
  { id: "scan", label: "New scan", icon: Plus },
  { id: "issues", label: "Issues", icon: AlertCircle },
  { id: "journeys", label: "User journeys", icon: Target },
  { id: "reports", label: "Reports", icon: FileText },
  { id: "integrations", label: "Integrations", icon: GitBranch },
  { id: "settings", label: "Settings", icon: Settings },
];

function AccessLens() {
  const [inApp, setInApp] = useState(false);
  const [view, setView] = useState<View>("overview");
  const [mobileNav, setMobileNav] = useState(false);
  const [selectedIssue, setSelectedIssue] = useState<Issue | null>(null);
  const [scanRunning, setScanRunning] = useState(false);
  const [scanDone, setScanDone] = useState(false);
  const [url, setUrl] = useState("https://demo-store.com");

  const openDemo = () => {
    setInApp(true);
    setView("overview");
    setScanDone(true);
  };

  const runScan = () => {
    setInApp(true);
    setSelectedIssue(null);
    setView("scan");
    setScanRunning(true);
    setScanDone(false);
    window.setTimeout(() => {
      setScanRunning(false);
      setScanDone(true);
      setView("overview");
    }, 1800);
  };

  if (!inApp) return <Landing onDemo={openDemo} onScan={runScan} />;

  return (
    <div className="min-h-screen bg-canvas text-ink">
      <AppShell
        view={view}
        setView={(next) => { setView(next); setSelectedIssue(null); setMobileNav(false); }}
        mobileNav={mobileNav}
        setMobileNav={setMobileNav}
        onNewScan={() => { setView("scan"); setScanDone(false); }}
      >
        {selectedIssue ? (
          <IssueDetail issue={selectedIssue} onBack={() => setSelectedIssue(null)} />
        ) : view === "overview" ? (
          <Overview onIssue={setSelectedIssue} onScan={() => setView("scan")} scanDone={scanDone} />
        ) : view === "scan" ? (
          <NewScan url={url} setUrl={setUrl} running={scanRunning} done={scanDone} onStart={runScan} />
        ) : view === "issues" ? (
          <Issues onIssue={setSelectedIssue} />
        ) : view === "journeys" ? (
          <Journeys />
        ) : view === "reports" ? (
          <Reports />
        ) : view === "integrations" ? (
          <Integrations />
        ) : (
          <SettingsView />
        )}
      </AppShell>
    </div>
  );
}

function Landing({ onDemo, onScan }: { onDemo: () => void; onScan: () => void }) {
  return (
    <div className="min-h-screen bg-canvas text-ink antialiased">
      <header className="sticky top-0 z-30 border-b border-rule bg-surface/80 backdrop-blur-md">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-3.5">
          <Brand />
          <nav className="hidden items-center gap-7 text-[13px] font-medium text-muted md:flex"><a className="text-ink" href="#method">Method</a><a href="#journey">Journey</a><a href="#reports">Reports</a></nav>
          <div className="flex items-center gap-3"><button className="rounded-md border border-rule px-3 py-1.5 text-[13px] font-medium transition-colors hover:bg-ink/5">Sign in</button><button onClick={onDemo} className="rounded-md bg-action px-3.5 py-1.5 text-[13px] font-semibold text-surface transition-colors hover:bg-navy">Try demo</button></div>
        </div>
      </header>
      <main>
        <section className="relative border-b border-rule">
          <div className="mx-auto grid max-w-6xl items-center gap-10 px-6 py-14 lg:grid-cols-12 lg:py-20">
            <div className="animate-rise lg:col-span-5">
              <p className="font-mono text-[11px] uppercase tracking-[0.2em] text-action">Automated accessibility audit</p>
              <h1 className="mt-5 max-w-[18ch] text-balance text-5xl font-extrabold leading-[1.03] tracking-tight text-navy">Audit the experience, not just the code.</h1>
              <p className="mt-5 max-w-[46ch] text-pretty text-[15px] leading-relaxed text-muted">AccessLens analyzes a real, rendered website for accessibility barriers, explains who is affected, and hands developers a precise route to fix.</p>
              <div className="mt-7 flex flex-wrap items-center gap-3"><button onClick={onScan} className="rounded-md bg-navy px-5 py-2.5 text-sm font-semibold text-surface transition-colors hover:bg-action">Start free scan</button><button onClick={onDemo} className="rounded-md border border-rule px-5 py-2.5 text-sm font-semibold transition-colors hover:bg-ink/5">View demo report</button></div>
              <div className="mt-8 grid grid-cols-3 gap-4 border-t border-rule pt-5"><Stat value="214" label="Rules checked" /><Stat value="WCAG 2.2" label="A · AA · AAA" /><Stat value="7" label="Test personas" /></div>
            </div>
            <div className="animate-rise lg:col-span-7" style={{ animationDelay: "100ms" }}><ReportMockup onIssue={onDemo} /></div>
          </div>
        </section>
        <section id="method" className="mx-auto max-w-6xl px-6 py-16"><div className="flex items-end justify-between border-b border-rule pb-4"><h2 className="text-balance text-2xl font-bold tracking-tight text-navy">What the instrument measures</h2><span className="font-mono text-[11px] uppercase tracking-wider text-muted">(a) Capabilities</span></div><div className="mt-8 grid gap-px overflow-hidden rounded-lg border border-rule bg-rule sm:grid-cols-3"><Feature number="01" title="Automated analysis" text="Rendered HTML, ARIA, forms, focus order and contrast signals in one pass." /><Feature number="02" title="Journey testing" text="Walk login, checkout and forms as a keyboard-only or screen-reader user." /><Feature number="03" title="Developer fixes" text="Each barrier names the element, the WCAG reference and a suggested patch." /></div></section>
        <section id="journey" className="border-t border-rule bg-navy"><div className="mx-auto flex max-w-6xl flex-col gap-3 px-6 py-6 sm:flex-row sm:items-center sm:justify-between"><p className="max-w-[62ch] text-pretty text-[13px] leading-relaxed text-surface/75">Automated testing identifies detectable accessibility barriers but does not constitute certification or guarantee full WCAG compliance. Human evaluation may still be required.</p><span className="shrink-0 font-mono text-[11px] uppercase tracking-wider text-surface/50">Not a legal determination</span></div></section>
      </main>
    </div>
  );
}

function AppShell({ children, view, setView, mobileNav, setMobileNav, onNewScan }: { children: React.ReactNode; view: View; setView: (view: View) => void; mobileNav: boolean; setMobileNav: (value: boolean) => void; onNewScan: () => void }) {
  return <div className="flex min-h-screen"><aside className={`fixed inset-y-0 left-0 z-40 flex w-64 flex-col border-r border-rule bg-surface transition-transform lg:static lg:translate-x-0 ${mobileNav ? "translate-x-0" : "-translate-x-full"}`}><div className="flex h-16 items-center border-b border-rule px-5"><Brand /></div><div className="flex-1 px-3 py-5"><p className="px-3 pb-2 font-mono text-[10px] uppercase tracking-[0.17em] text-muted">Workspace</p><nav className="space-y-1">{navItems.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setView(id)} className={`flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-left text-sm font-medium transition-colors ${view === id ? "bg-navy text-surface" : "text-muted hover:bg-ink/5 hover:text-ink"}`}><Icon className="size-4" />{label}{id === "issues" && <span className={`ml-auto rounded-full px-1.5 py-0.5 font-mono text-[10px] ${view === id ? "bg-surface/15 text-surface" : "bg-critical/10 text-critical"}`}>15</span>}</button>)}</nav><div className="mt-7 rounded-lg border border-rule bg-canvas p-3"><div className="flex items-center gap-2"><span className="relative size-2 rounded-full bg-passed"><span className="absolute size-2 animate-ping rounded-full bg-passed/50" /></span><span className="text-xs font-semibold">DemoStore</span></div><p className="mt-2 truncate font-mono text-[10px] text-muted">demo-store.com</p><button onClick={onNewScan} className="mt-3 flex w-full items-center justify-center gap-2 rounded-md border border-rule bg-surface py-1.5 text-xs font-semibold hover:bg-ink/5"><Plus className="size-3.5" /> New scan</button></div></div><div className="border-t border-rule p-3"><div className="flex items-center gap-3 rounded-md px-3 py-2"><div className="grid size-8 place-items-center rounded-full bg-navy text-xs font-bold text-surface">JD</div><div className="min-w-0"><p className="truncate text-xs font-semibold">Jordan Davis</p><p className="truncate font-mono text-[10px] text-muted">Pro workspace</p></div><ChevronDown className="ml-auto size-3.5 text-muted" /></div></div></aside><div className="flex min-w-0 flex-1 flex-col"><header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-rule bg-surface/80 px-4 backdrop-blur-md lg:px-8"><div className="flex items-center gap-3"><button onClick={() => setMobileNav(!mobileNav)} className="rounded-md p-2 text-muted hover:bg-ink/5 lg:hidden" aria-label="Open navigation"><Menu className="size-5" /></button><div className="hidden items-center gap-2 text-xs text-muted sm:flex"><Search className="size-4" /><span>Search sites, issues, journeys…</span><kbd className="ml-2 rounded border border-rule px-1.5 py-0.5 font-mono text-[9px]">⌘K</kbd></div><span className="font-mono text-[10px] uppercase tracking-wider text-muted sm:hidden">AccessLens</span></div><div className="flex items-center gap-2"><button className="rounded-md p-2 text-muted hover:bg-ink/5" aria-label="Notifications"><Bell className="size-4" /></button><div className="hidden h-5 w-px bg-rule sm:block" /><div className="grid size-8 place-items-center rounded-full bg-navy text-xs font-bold text-surface">JD</div></div></header><main className="flex-1 px-4 py-7 sm:px-6 lg:px-10">{children}</main></div></div>;
}

function Overview({ onIssue, onScan, scanDone }: { onIssue: (issue: Issue) => void; onScan: () => void; scanDone: boolean }) {
  return <div className="mx-auto max-w-7xl animate-rise"><PageHeading eyebrow="Demo scan · Sep 20, 2026" title="Accessibility audit" description="Audit the experience, not just the code." action={<button onClick={onScan} className="flex items-center gap-2 rounded-md bg-navy px-4 py-2.5 text-sm font-semibold text-surface hover:bg-action"><Plus className="size-4" /> New scan</button>} />{scanDone && <div className="mb-5 flex items-center gap-3 rounded-md border border-passed/20 bg-passed/10 px-4 py-3 text-sm text-passed"><CheckCircle2 className="size-4" /> Demo scan loaded with 15 intentional findings across 7 pages. <span className="font-mono text-[10px] uppercase tracking-wider">mock data</span></div>}<div className="grid gap-5 xl:grid-cols-[1.25fr_1fr_1fr]"><ScoreCard /><SeverityCard /><RegressionCard /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.45fr_1fr]"><IssueList issues={issues.slice(0, 5)} onIssue={onIssue} /><JourneyCard /></div><div className="mt-5 grid gap-5 md:grid-cols-2"><CategoryCard /><HistoryCard /></div><Disclaimer /></div>;
}

function NewScan({ url, setUrl, running, done, onStart }: { url: string; setUrl: (value: string) => void; running: boolean; done: boolean; onStart: () => void }) {
  const steps = ["Initializing browser", "Loading website", "Analyzing DOM", "Inspecting accessibility tree", "Checking contrast", "Checking forms", "Checking keyboard/focus behavior", "Analyzing user journeys", "Generating report"];
  return <div className="mx-auto max-w-5xl animate-rise"><PageHeading eyebrow="Workspace / New scan" title="Start accessibility scan" description="Analyze a rendered website state with a deterministic set of accessibility checks." /><div className="grid gap-5 lg:grid-cols-[1.1fr_0.9fr]"><div className="rounded-lg border border-rule bg-surface p-6"><div className="flex items-center gap-2"><Globe2 className="size-4 text-action" /><h2 className="font-semibold">Scan target</h2></div><label className="mt-6 block text-sm font-medium">Website URL<input value={url} onChange={(event) => setUrl(event.target.value)} className="mt-2 h-11 w-full rounded-md border border-rule bg-canvas px-3 font-mono text-sm outline-none transition focus:border-action focus:ring-2 focus:ring-action/20" placeholder="https://example.com" /></label><div className="mt-6 grid gap-3 sm:grid-cols-3"><Choice title="Single page" text="Fastest" selected /><Choice title="Website crawl" text="Up to 50 pages" /><Choice title="Important journey" text="Flows & forms" /></div><div className="mt-7 border-t border-rule pt-5"><div className="flex items-center justify-between"><h3 className="text-sm font-semibold">Standards and scope</h3><button className="flex items-center gap-1.5 text-xs font-semibold text-action"><Settings className="size-3.5" /> Advanced settings</button></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><select className="h-10 rounded-md border border-rule bg-surface px-3 text-sm"><option>WCAG 2.2</option><option>WCAG 2.1</option></select><select className="h-10 rounded-md border border-rule bg-surface px-3 text-sm"><option>Level AA</option><option>Level A</option><option>Level AAA</option></select></div></div><button onClick={onStart} disabled={running} className="mt-8 flex h-11 w-full items-center justify-center gap-2 rounded-md bg-navy text-sm font-semibold text-surface transition hover:bg-action disabled:opacity-60">{running ? <><Zap className="size-4 animate-pulse" /> Scanning {url.replace("https://", "")}…</> : <><Play className="size-4" /> {done ? "Re-scan demo website" : "Start scan"}</>}</button><p className="mt-3 text-center text-xs text-muted">Try Demo uses intentional local findings; it does not scan the submitted URL.</p></div><ScanProgress running={running} done={done} steps={steps} /></div></div>;
}

function ScanProgress({ running, done, steps }: { running: boolean; done: boolean; steps: string[] }) { const activeIndex = done ? steps.length : running ? 6 : 0; return <div className="rounded-lg border border-rule bg-surface p-6"><div className="flex items-center justify-between border-b border-rule pb-4"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Scan progress</p><h2 className="mt-1 font-semibold">{done ? "Report ready" : running ? "Analyzing DemoStore" : "Ready when you are"}</h2></div><span className={`rounded-full px-2 py-1 font-mono text-[10px] uppercase tracking-wider ${done ? "bg-passed/10 text-passed" : running ? "bg-action/10 text-action" : "bg-ink/5 text-muted"}`}>{done ? "Complete" : running ? "In progress" : "Idle"}</span></div><div className="mt-5 space-y-3">{steps.map((step, index) => <div key={step} className={`relative flex items-center gap-3 overflow-hidden text-sm ${index > activeIndex ? "text-muted/60" : "text-ink"}`}><span className={`grid size-5 shrink-0 place-items-center rounded-full border ${index < activeIndex ? "border-passed bg-passed text-surface" : index === activeIndex && running ? "border-action text-action" : "border-rule text-muted"}`}>{index < activeIndex || done ? <Check className="size-3" /> : index === activeIndex && running ? <span className="size-1.5 animate-pulse rounded-full bg-action" /> : <span className="font-mono text-[9px]">{index + 1}</span>}</span><span className="flex-1">{step}</span>{index === activeIndex && running && <span className="font-mono text-[10px] text-action">…</span>}{index < activeIndex && <span className="font-mono text-[10px] text-passed">done</span>}{index === activeIndex && running && <span className="absolute inset-y-0 left-0 w-1/4 animate-sweep bg-action/10" />}</div>)}</div></div>; }

function Issues({ onIssue }: { onIssue: (issue: Issue) => void }) { const [severity, setSeverity] = useState("All severities"); const filtered = severity === "All severities" ? issues : issues.filter((issue) => severityMeta[issue.severity].label === severity); return <div className="mx-auto max-w-7xl animate-rise"><PageHeading eyebrow="Workspace / Findings" title="Issues" description="Detectable barriers from the DemoStore rendered experience." action={<button className="flex items-center gap-2 rounded-md border border-rule px-3 py-2 text-sm font-semibold hover:bg-ink/5"><Download className="size-4" /> Export CSV</button>} /><div className="mb-5 flex flex-wrap items-center gap-2 rounded-lg border border-rule bg-surface p-3"><ListFilter className="ml-1 size-4 text-muted" /><select value={severity} onChange={(event) => setSeverity(event.target.value)} className="h-9 rounded-md border border-rule bg-surface px-3 text-xs font-medium"><option>All severities</option><option>Critical</option><option>Serious</option><option>Moderate</option></select><select className="h-9 rounded-md border border-rule bg-surface px-3 text-xs font-medium"><option>All categories</option><option>Keyboard</option><option>Forms</option><option>Color</option><option>ARIA</option><option>Images</option><option>Structure</option></select><select className="h-9 rounded-md border border-rule bg-surface px-3 text-xs font-medium"><option>Open issues</option><option>Fixed</option><option>Ignored</option></select><span className="ml-auto font-mono text-[10px] uppercase tracking-wider text-muted">{filtered.length} findings</span></div><div className="overflow-hidden rounded-lg border border-rule bg-surface"><div className="hidden grid-cols-[110px_1fr_180px_150px_90px] gap-4 border-b border-rule bg-canvas px-5 py-3 font-mono text-[10px] uppercase tracking-wider text-muted md:grid"><span>Severity</span><span>Finding</span><span>WCAG criterion</span><span>Page</span><span /></div>{filtered.map((issue) => <button key={issue.id} onClick={() => onIssue(issue)} className="grid w-full gap-3 border-b border-rule px-5 py-4 text-left transition-colors last:border-0 hover:bg-ink/[0.025] md:grid-cols-[110px_1fr_180px_150px_90px] md:items-center md:gap-4"><span className={`flex w-fit items-center gap-1.5 rounded px-2 py-1 font-mono text-[10px] font-medium uppercase tracking-wider ${severityMeta[issue.severity].className}`}><span className={`size-1.5 rounded-full ${severityMeta[issue.severity].dot}`} />{severityMeta[issue.severity].label}</span><span className="min-w-0"><strong className="block truncate text-sm font-semibold">{issue.title}</strong><span className="mt-1 block truncate font-mono text-[10px] text-muted">{issue.selector}</span></span><span className="text-xs text-muted">{issue.wcag}</span><span className="font-mono text-xs text-muted">{issue.page}</span><span className="flex items-center gap-1 text-xs font-semibold text-action">Details <ArrowRight className="size-3.5" /></span></button>)}</div></div>; }

function IssueDetail({ issue, onBack }: { issue: Issue; onBack: () => void }) { const [copied, setCopied] = useState(false); const [fixed, setFixed] = useState(false); const meta = severityMeta[issue.severity]; const copyFix = () => { void navigator.clipboard?.writeText(issue.fix); setCopied(true); window.setTimeout(() => setCopied(false), 1600); }; return <div className="mx-auto max-w-7xl animate-rise"><button onClick={onBack} className="mb-5 flex items-center gap-2 text-sm font-semibold text-muted hover:text-ink"><ArrowLeft className="size-4" /> Back to issues</button><div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><div><div className="mb-5"><div className="flex flex-wrap items-center gap-2"><span className={`rounded px-2 py-1 font-mono text-[10px] font-medium uppercase tracking-wider ${meta.className}`}>{meta.label}</span><span className="font-mono text-[10px] uppercase tracking-wider text-muted">Issue AL-{String(issue.id).padStart(3, "0")}</span></div><h1 className="mt-3 text-3xl font-bold tracking-tight text-navy">{issue.title}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted">Detected on <span className="font-mono text-ink">{issue.page}</span> · {issue.wcag}</p></div><PreviewCanvas issue={issue} /><div className="mt-5 rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Detected element</p><p className="mt-1 text-sm font-semibold">Rendered DOM excerpt</p></div><button onClick={() => void navigator.clipboard?.writeText(issue.selector)} className="rounded-md p-2 text-muted hover:bg-ink/5" aria-label="Copy detected element"><Copy className="size-4" /></button></div><pre className="mt-4 overflow-x-auto rounded-md bg-navy p-4 font-mono text-xs leading-relaxed text-surface">{issue.selector}{"\n"}  <span className="text-surface/55">{/* affected element */}</span></pre></div></div><div className="space-y-5"><div className="rounded-lg border border-rule bg-surface p-5"><p className="font-mono text-[10px] uppercase tracking-wider text-action">Why this matters</p><h2 className="mt-2 text-lg font-bold text-navy">Understand the impact</h2><p className="mt-3 text-sm leading-relaxed text-muted">{issue.explanation}</p><div className="mt-4 flex items-start gap-3 rounded-md bg-canvas p-3"><UserRound className="mt-0.5 size-4 shrink-0 text-action" /><div><p className="text-xs font-semibold">Who may be affected?</p><p className="mt-1 text-xs text-muted">{issue.users}</p></div></div></div><div className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-wider text-passed">Suggested fix</p><h2 className="mt-2 text-lg font-bold text-navy">A patch developers can ship</h2></div><Code2 className="size-5 text-action" /></div><pre className="mt-4 overflow-x-auto rounded-md bg-navy p-4 font-mono text-xs leading-relaxed text-surface">{issue.fix}</pre><div className="mt-4 flex flex-wrap gap-2"><button onClick={copyFix} className="flex items-center gap-2 rounded-md bg-navy px-3 py-2 text-xs font-semibold text-surface hover:bg-action">{copied ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}{copied ? "Copied" : "Copy fix"}</button><button onClick={() => setFixed(true)} className={`flex items-center gap-2 rounded-md border px-3 py-2 text-xs font-semibold ${fixed ? "border-passed/30 bg-passed/10 text-passed" : "border-rule hover:bg-ink/5"}`}>{fixed ? <CheckCircle2 className="size-3.5" /> : <Check className="size-3.5" />}{fixed ? "Marked fixed" : "Mark as fixed"}</button><button className="rounded-md border border-rule px-3 py-2 text-xs font-semibold hover:bg-ink/5">Ignore</button></div></div><div className="rounded-lg border border-action/20 bg-action/5 p-5"><div className="flex items-center gap-2"><Sparkles className="size-4 text-action" /><h2 className="text-sm font-bold text-navy">AccessLens Copilot</h2><span className="rounded-full bg-action/10 px-2 py-0.5 font-mono text-[9px] uppercase tracking-wider text-action">Explain</span></div><p className="mt-3 text-sm leading-relaxed text-muted">The button contains only an icon and does not expose an accessible name. A screen reader may announce it only as “button”. Add a meaningful accessible name using visible text or <code className="rounded bg-action/10 px-1 font-mono text-xs text-action">aria-label</code>.</p><div className="mt-4 flex flex-wrap gap-2"><button className="rounded-full border border-action/20 bg-surface px-3 py-1.5 text-xs font-medium hover:bg-action/10">React version</button><button className="rounded-full border border-action/20 bg-surface px-3 py-1.5 text-xs font-medium hover:bg-action/10">Why screen readers?</button></div></div></div></div><Disclaimer /></div>; }

function Journeys() { const [persona, setPersona] = useState("Keyboard-only user"); return <div className="mx-auto max-w-7xl animate-rise"><PageHeading eyebrow="Workspace / User journeys" title="Accessibility journeys" description="Test important workflows using a simulation/testing profile — not a claim to perfectly reproduce lived experience." action={<button className="flex items-center gap-2 rounded-md bg-navy px-4 py-2.5 text-sm font-semibold text-surface hover:bg-action"><Plus className="size-4" /> New journey</button>} /><div className="mb-5 flex flex-wrap gap-2">{["Keyboard-only user", "Screen-reader user", "Low-vision user", "Color-vision deficiency", "Motor impairment"].map((item) => <button key={item} onClick={() => setPersona(item)} className={`rounded-full border px-3 py-1.5 text-xs font-medium ${persona === item ? "border-action bg-action/10 text-action" : "border-rule text-muted hover:bg-ink/5"}`}>{item}</button>)}</div><div className="grid gap-5 lg:grid-cols-[1fr_0.85fr]"><div className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between border-b border-rule pb-4"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Purchase journey</p><h2 className="mt-1 text-lg font-bold text-navy">Checkout with {persona}</h2></div><span className="rounded-full bg-serious/10 px-2.5 py-1 font-mono text-[10px] uppercase tracking-wider text-serious">Blocked</span></div><div className="mt-5 space-y-4">{[{ label: "Open website", status: "done" }, { label: "Search product", status: "done" }, { label: "Open product", status: "done" }, { label: "Add to cart", status: "done" }, { label: "Open checkout", status: "done" }, { label: "Enter payment", status: "warn" }, { label: "Confirm payment", status: "fail" }].map((step, index) => <div key={step.label} className="flex items-center gap-3"><div className={`grid size-7 place-items-center rounded-full ${step.status === "done" ? "bg-passed/10 text-passed" : step.status === "warn" ? "bg-serious/10 text-serious" : "bg-critical/10 text-critical"}`}>{step.status === "done" ? <Check className="size-4" /> : step.status === "warn" ? <AlertCircle className="size-4" /> : <X className="size-4" />}</div><div className="flex-1"><p className="text-sm font-semibold">{step.label}</p><p className="font-mono text-[10px] text-muted">Step {index + 1} · DemoStore</p></div><span className={`font-mono text-[10px] uppercase tracking-wider ${step.status === "done" ? "text-passed" : step.status === "warn" ? "text-serious" : "text-critical"}`}>{step.status === "done" ? "passed" : step.status === "warn" ? "warning" : "blocked"}</span></div>)}</div></div><div className="space-y-5"><div className="rounded-lg border border-critical/20 bg-critical/5 p-5"><div className="flex items-center gap-2"><AlertCircle className="size-4 text-critical" /><h2 className="font-bold text-navy">Journey blocked</h2></div><p className="mt-3 text-sm leading-relaxed text-muted">Keyboard focus was lost when the payment modal opened. The confirm button cannot be reached without moving focus behind the dialog.</p><button className="mt-4 flex items-center gap-2 text-xs font-semibold text-action">View related issue <ArrowRight className="size-3.5" /></button></div><div className="rounded-lg border border-rule bg-surface p-5"><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Journey health</p><div className="mt-3 flex items-end justify-between"><span className="font-mono text-4xl font-medium text-navy">71%</span><span className="font-mono text-xs text-serious">Needs attention</span></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-ink/10"><div className="h-full w-[71%] rounded-full bg-serious" /></div></div></div></div></div>; }

function Reports() { const [generated, setGenerated] = useState(false); return <div className="mx-auto max-w-6xl animate-rise"><PageHeading eyebrow="Workspace / Reports" title="Generate a professional report" description="Share a clear record of automated findings, fixes, and limitations with your team or clients." action={<button onClick={() => setGenerated(true)} className="flex items-center gap-2 rounded-md bg-navy px-4 py-2.5 text-sm font-semibold text-surface hover:bg-action"><FileText className="size-4" /> Generate report</button>} />{generated && <div className="mb-5 flex items-center gap-3 rounded-md border border-passed/20 bg-passed/10 px-4 py-3 text-sm text-passed"><CheckCircle2 className="size-4" /> Report prepared for DemoStore. Choose an export format below.</div>}<div className="grid gap-5 md:grid-cols-2">{[{ icon: FileText, title: "PDF report", text: "Presentation-ready audit with severity summary, findings, and recommendations." }, { icon: Globe2, title: "HTML report", text: "Shareable interactive report with expandable issue details." }, { icon: Terminal, title: "CSV export", text: "Issue rows for planning, triage, and project management workflows." }, { icon: Code2, title: "JSON export", text: "Normalized findings ready for future CI and API integrations." }].map(({ icon: Icon, title, text }) => <div key={title} className="flex items-start gap-4 rounded-lg border border-rule bg-surface p-5"><div className="grid size-10 shrink-0 place-items-center rounded-md bg-action/10 text-action"><Icon className="size-5" /></div><div className="flex-1"><h2 className="font-semibold text-navy">{title}</h2><p className="mt-1 text-sm leading-relaxed text-muted">{text}</p><button className="mt-4 flex items-center gap-2 text-xs font-semibold text-action">Download <Download className="size-3.5" /></button></div></div>)}</div><div className="mt-5 rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between border-b border-rule pb-4"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">White-label settings</p><h2 className="mt-1 font-semibold text-navy">Agency report identity</h2></div><span className="font-mono text-[10px] text-muted">optional</span></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-sm font-medium">Company name<input className="mt-2 h-10 w-full rounded-md border border-rule bg-canvas px-3 text-sm" placeholder="Your agency" /></label><label className="text-sm font-medium">Report subtitle<input className="mt-2 h-10 w-full rounded-md border border-rule bg-canvas px-3 text-sm" placeholder="Accessibility audit · Q3" /></label></div></div><Disclaimer /></div>; }

function Integrations() { return <div className="mx-auto max-w-6xl animate-rise"><PageHeading eyebrow="Workspace / Integrations" title="Integrations" description="Connect accessibility checks to the tools your delivery team already uses." /><div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{[{ title: "GitHub", text: "Run checks on pull requests and annotate changed files.", icon: GitBranch, status: "Available" }, { title: "GitHub Actions", text: "Fail CI when new critical or serious findings appear.", icon: Zap, status: "Available" }, { title: "Vercel", text: "Watch deployments and compare accessibility health over time.", icon: Globe2, status: "Coming soon" }, { title: "GitLab", text: "Add audit results to merge request discussions.", icon: GitBranch, status: "Coming soon" }, { title: "Netlify", text: "Monitor production deploys for accessibility regressions.", icon: Globe2, status: "Coming soon" }, { title: "WordPress", text: "Scan WordPress pages and monitor accessibility changes.", icon: Link2, status: "Not connected" }].map(({ title, text, icon: Icon, status }) => <div key={title} className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><div className="grid size-10 place-items-center rounded-md bg-navy text-surface"><Icon className="size-5" /></div><span className={`rounded-full px-2 py-1 font-mono text-[9px] uppercase tracking-wider ${status === "Available" ? "bg-passed/10 text-passed" : "bg-ink/5 text-muted"}`}>{status}</span></div><h2 className="mt-5 font-semibold text-navy">{title === "WordPress" ? "AccessLens WordPress Plugin" : title}</h2><p className="mt-2 min-h-12 text-sm leading-relaxed text-muted">{text}</p><button className="mt-5 flex items-center gap-2 rounded-md border border-rule px-3 py-2 text-xs font-semibold hover:bg-ink/5">{status === "Not connected" ? "Connect WordPress" : status === "Available" ? "Configure" : "Learn more"}<ArrowRight className="size-3.5" /></button></div>)}</div><div className="mt-5 rounded-lg border border-rule bg-surface p-5"><div className="flex items-center gap-2"><GitBranch className="size-4 text-action" /><h2 className="font-semibold text-navy">GitHub Pull Request #42</h2><span className="ml-auto rounded-full bg-critical/10 px-2 py-1 font-mono text-[10px] uppercase tracking-wider text-critical">Failed</span></div><div className="mt-4 rounded-md bg-navy p-4 font-mono text-xs text-surface"><p className="text-critical">✕ Accessibility check failed</p><p className="mt-2 text-surface/70">5 new accessibility issues · Critical: 2 · Serious: 3</p><p className="mt-2 text-surface/70">Affected: Login.tsx · CheckoutModal.tsx · Navbar.tsx</p></div></div></div>; }

function SettingsView() { return <div className="mx-auto max-w-4xl animate-rise"><PageHeading eyebrow="Workspace / Settings" title="Settings" description="Manage your AccessLens workspace preferences." /><div className="rounded-lg border border-rule bg-surface p-6"><div className="flex items-center gap-3 border-b border-rule pb-5"><div className="grid size-10 place-items-center rounded-full bg-navy text-sm font-bold text-surface">JD</div><div><h2 className="font-semibold text-navy">Jordan Davis</h2><p className="text-sm text-muted">jordan@demo-company.com</p></div><button className="ml-auto rounded-md border border-rule px-3 py-2 text-xs font-semibold hover:bg-ink/5">Edit profile</button></div><div className="grid gap-5 pt-5 sm:grid-cols-2"><label className="text-sm font-medium">Workspace name<input className="mt-2 h-10 w-full rounded-md border border-rule bg-canvas px-3 text-sm" value="Demo Company" readOnly /></label><label className="text-sm font-medium">Default standard<select className="mt-2 h-10 w-full rounded-md border border-rule bg-canvas px-3 text-sm"><option>WCAG 2.2 · Level AA</option><option>WCAG 2.1 · Level AA</option></select></label></div></div></div>; }

function ReportMockup({ onIssue }: { onIssue: () => void }) { return <div className="rounded-xl border border-rule bg-surface p-5 shadow-[0_1px_0_0_var(--rule)]"><div className="flex items-center justify-between border-b border-rule pb-4"><div className="flex items-center gap-3"><span className="size-2 rounded-full bg-serious" /><div><div className="text-sm font-semibold tracking-tight">demo-store.com</div><div className="font-mono text-[11px] text-muted">Scan 20 Sep 2026 · Needs attention</div></div></div><div className="flex items-center gap-2 rounded-md border border-rule bg-canvas px-3 py-1.5"><span className="relative block size-1.5 rounded-full bg-passed" /><span className="font-mono text-[11px] text-muted">Demo scan</span></div></div><div className="mt-5 grid grid-cols-3 gap-5"><div className="flex flex-col items-center justify-center rounded-lg bg-canvas/60 py-4"><div className="score-ring grid size-24 place-items-center"><div className="grid size-[4.5rem] place-items-center rounded-full bg-surface"><div className="text-center"><div className="font-mono text-2xl font-medium text-navy">78</div><div className="text-[9px] uppercase tracking-wider text-muted">of 100</div></div></div></div><div className="mt-3 text-[11px] font-medium uppercase tracking-wider text-muted">Health score</div></div><div className="col-span-2 grid grid-cols-2 gap-3">{(["critical", "serious", "moderate", "passed"] as const).map((key) => <div key={key} className="rounded-lg border border-rule p-3"><div className="flex items-center gap-1.5"><span className={`size-2 rounded-full ${key === "passed" ? "bg-passed" : `bg-${key}`}`} /><span className="text-[11px] uppercase tracking-wider text-muted">{key}</span></div><div className={`mt-1 font-mono text-xl font-medium ${key === "passed" ? "text-passed" : `text-${key}`}`}>{key === "critical" ? 3 : key === "serious" ? 7 : key === "moderate" ? 12 : 84}</div></div>)}</div></div><div className="mt-5 space-y-2.5">{issues.slice(0, 3).map((issue) => <button key={issue.id} onClick={onIssue} className="flex w-full items-center gap-3 rounded-md border border-rule px-3 py-2.5 text-left transition-colors hover:bg-ink/[0.03]"><span className={`size-2 shrink-0 rounded-full ${severityMeta[issue.severity].dot}`} /><span className={`rounded px-1.5 py-0.5 font-mono text-[10px] font-medium uppercase ${severityMeta[issue.severity].className}`}>{severityMeta[issue.severity].label}</span><span className="min-w-0 flex-1 truncate text-[13px]">{issue.title}</span><span className="hidden font-mono text-[11px] text-muted sm:inline">{issue.wcag.split(" ")[0]}</span><ArrowRight className="size-3.5 text-muted" /></button>)}</div><div className="mt-5 overflow-hidden rounded-md border border-rule"><div className="flex items-center justify-between bg-navy px-3 py-2"><span className="font-mono text-[11px] uppercase tracking-wider text-surface/80">Scan progress</span><span className="font-mono text-[11px] text-surface/60">9 / 9</span></div><div className="divide-y divide-rule text-[12px]"><div className="flex items-center justify-between px-3 py-1.5"><span className="text-muted">Inspecting accessibility tree</span><span className="text-passed">✓</span></div><div className="flex items-center justify-between px-3 py-1.5"><span className="text-muted">Checking keyboard &amp; focus</span><span className="text-passed">✓</span></div><div className="flex items-center justify-between px-3 py-1.5"><span className="text-ink">Report generated</span><span className="text-passed">✓</span></div></div></div></div>; }

function PreviewCanvas({ issue }: { issue: Issue }) { return <div className="overflow-hidden rounded-lg border border-rule bg-surface"><div className="flex items-center justify-between border-b border-rule bg-navy px-4 py-2.5"><div className="flex items-center gap-2 text-xs font-semibold text-surface"><Globe2 className="size-3.5" /> demo-store.com</div><span className="font-mono text-[10px] text-surface/60">{issue.page}</span></div><div className="relative min-h-[310px] bg-canvas p-6"><div className="flex items-center justify-between border-b border-rule pb-4"><div className="flex items-center gap-2 font-bold text-navy"><span className="grid size-7 place-items-center rounded bg-action text-[10px] text-surface">DS</span> DemoStore</div><div className="flex gap-4 font-mono text-[10px] text-muted"><span>Products</span><span>Cart</span><span>Login</span></div></div><div className="mx-auto mt-8 max-w-md text-center"><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-action">Running essentials</p><h3 className="mt-2 text-2xl font-bold text-navy">Move with confidence.</h3><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-md border border-rule bg-surface p-3 text-left"><div className="h-20 rounded bg-navy/10" /><p className="mt-2 text-xs font-semibold">Trail runner</p><p className="font-mono text-[10px] text-muted">$129.00</p></div><div className="rounded-md border border-rule bg-surface p-3 text-left"><div className="h-20 rounded bg-action/15" /><p className="mt-2 text-xs font-semibold">Daily trainer</p><p className="font-mono text-[10px] text-muted">$99.00</p></div></div></div><span className="absolute left-[55%] top-[58%] grid size-7 place-items-center rounded-full border-2 border-surface bg-critical text-xs font-bold text-surface shadow-lg">!</span><span className="absolute left-[55%] top-[58%] size-7 animate-ping rounded-full bg-critical/50" /><div className="absolute bottom-4 left-4 flex items-center gap-3 rounded-md border border-rule bg-surface px-3 py-2 text-[10px] text-muted"><span className="size-1.5 rounded-full bg-critical" /> Affected element highlighted · click Open Element to inspect</div></div></div>; }

function ScoreCard() { return <div className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Automated accessibility health</p><h2 className="mt-1 text-lg font-bold text-navy">DemoStore report</h2></div><span className="rounded-full bg-serious/10 px-2.5 py-1 font-mono text-[10px] uppercase tracking-wider text-serious">Needs attention</span></div><div className="mt-5 flex items-center gap-5"><div className="score-ring grid size-28 shrink-0 place-items-center"><div className="grid size-[5.4rem] place-items-center rounded-full bg-surface"><div className="text-center"><div className="font-mono text-4xl font-medium text-navy">78</div><div className="font-mono text-[10px] uppercase tracking-wider text-muted">/ 100</div></div></div></div><div><p className="text-sm leading-relaxed text-muted">An internal AccessLens health score based on detected findings and test coverage.</p><p className="mt-3 font-mono text-[10px] text-muted">Not a WCAG compliance score.</p></div></div></div>; }

function SeverityCard() { return <div className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><h2 className="font-semibold text-navy">Findings by severity</h2><BarChart3 className="size-4 text-muted" /></div><div className="mt-5 space-y-4">{([{ key: "critical", value: 3, width: "w-[18%]" }, { key: "serious", value: 7, width: "w-[42%]" }, { key: "moderate", value: 12, width: "w-[70%]" }, { key: "passed", value: 84, width: "w-full" }] as const).map(({ key, value, width }) => <div key={key}><div className="flex justify-between font-mono text-[10px] uppercase tracking-wider"><span className={key === "passed" ? "text-passed" : `text-${key}`}>{key}</span><span>{value}</span></div><div className="mt-1.5 h-1.5 rounded-full bg-ink/10"><div className={`h-full rounded-full ${key === "passed" ? "bg-passed" : `bg-${key}`} ${width}`} /></div></div>)}</div></div>; }

function RegressionCard() { return <div className="rounded-lg border border-critical/20 bg-critical/5 p-5"><div className="flex items-center gap-2"><History className="size-4 text-critical" /><h2 className="font-semibold text-navy">Accessibility regression</h2></div><div className="mt-5 flex items-end gap-3"><div><span className="font-mono text-3xl text-muted">92</span><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Previous</p></div><ArrowRight className="mb-5 size-4 text-muted" /><div><span className="font-mono text-3xl text-critical">84</span><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Current</p></div></div><p className="mt-4 text-sm font-semibold text-critical">8-point decline</p><p className="mt-1 text-xs text-muted">5 new issues detected since Sep 17.</p></div>; }

function IssueList({ issues: list, onIssue }: { issues: Issue[]; onIssue: (issue: Issue) => void }) { return <div className="rounded-lg border border-rule bg-surface"><div className="flex items-center justify-between border-b border-rule px-5 py-4"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Priority findings</p><h2 className="mt-1 font-semibold text-navy">Open issues</h2></div><button className="text-xs font-semibold text-action">View all</button></div><div className="divide-y divide-rule">{list.map((issue) => <button key={issue.id} onClick={() => onIssue(issue)} className="flex w-full items-center gap-3 px-5 py-4 text-left hover:bg-ink/[0.025]"><span className={`size-2 shrink-0 rounded-full ${severityMeta[issue.severity].dot}`} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{issue.title}</p><p className="mt-1 truncate font-mono text-[10px] text-muted">{issue.wcag} · {issue.page}</p></div><ArrowRight className="size-4 shrink-0 text-muted" /></button>)}</div></div>; }

function JourneyCard() { return <div className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">User journey</p><h2 className="mt-1 font-semibold text-navy">Purchase journey</h2></div><span className="rounded-full bg-serious/10 px-2 py-1 font-mono text-[10px] uppercase tracking-wider text-serious">Blocked</span></div><div className="mt-5 space-y-3">{["Open website", "Search product", "Add to cart", "Open checkout", "Enter payment"].map((step, index) => <div key={step} className="flex items-center gap-3 text-sm"><span className={`grid size-5 place-items-center rounded-full ${index < 4 ? "bg-passed/10 text-passed" : "bg-serious/10 text-serious"}`}>{index < 4 ? <Check className="size-3" /> : <AlertCircle className="size-3" />}</span><span className={index === 4 ? "font-semibold" : "text-muted"}>{step}</span>{index === 4 && <span className="ml-auto font-mono text-[10px] text-serious">focus lost</span>}</div>)}</div><button className="mt-5 flex items-center gap-2 text-xs font-semibold text-action">Inspect journey <ArrowRight className="size-3.5" /></button></div>; }

function CategoryCard() { return <div className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Coverage map</p><h2 className="mt-1 font-semibold text-navy">Categories</h2></div><ShieldCheck className="size-4 text-action" /></div><div className="mt-5 grid grid-cols-2 gap-3">{[{ label: "Perceivable", value: 81 }, { label: "Operable", value: 68 }, { label: "Understandable", value: 88 }, { label: "Robust", value: 75 }].map((item) => <div key={item.label} className="rounded-md bg-canvas p-3"><div className="flex items-center justify-between"><span className="text-xs font-semibold">{item.label}</span><span className="font-mono text-xs text-action">{item.value}%</span></div><div className="mt-2 h-1.5 rounded-full bg-ink/10"><div className="h-full rounded-full bg-action" style={{ width: `${item.value}%` }} /></div></div>)}</div></div>; }

function HistoryCard() { return <div className="rounded-lg border border-rule bg-surface p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-wider text-muted">Scan history</p><h2 className="mt-1 font-semibold text-navy">Health over time</h2></div><span className="font-mono text-[10px] text-passed">▲ +6 pts</span></div><div className="mt-6 flex h-28 items-end gap-3">{[{ date: "Sep 05", value: 94 }, { date: "Sep 12", value: 89 }, { date: "Sep 17", value: 83 }, { date: "Sep 20", value: 78 }].map((item, index) => <div key={item.date} className="flex flex-1 flex-col items-center gap-2"><div className={`w-full rounded-t ${index === 3 ? "bg-action" : "bg-navy/30"}`} style={{ height: `${item.value}%` }} /><span className="font-mono text-[9px] text-muted">{item.date.replace("Sep ", "")}</span><span className="font-mono text-[10px] font-medium text-navy">{item.value}</span></div>)}</div></div>; }

function Disclaimer() { return <div className="mt-6 flex items-start gap-3 rounded-lg border border-rule bg-surface px-4 py-3 text-xs leading-relaxed text-muted"><CircleHelp className="mt-0.5 size-4 shrink-0 text-action" /><span>Automated accessibility testing cannot detect every barrier. Results are potential WCAG issues, not a certification or legal compliance determination. Human evaluation may still be required.</span></div>; }
function Brand() { return <div className="flex items-center gap-2.5"><span className="grid size-7 place-items-center rounded-md bg-navy font-mono text-[11px] font-medium text-surface">AL</span><span className="text-[15px] font-semibold tracking-tight">AccessLens</span><span className="ml-1 hidden rounded-full border border-rule px-2 py-0.5 font-mono text-[10px] uppercase tracking-wider text-muted sm:inline">Audit Dossier</span></div>; }
function Stat({ value, label }: { value: string; label: string }) { return <div><div className="font-mono text-lg font-medium text-navy">{value}</div><div className="text-[11px] uppercase tracking-wider text-muted">{label}</div></div>; }
function Feature({ number, title, text }: { number: string; title: string; text: string }) { return <div className="bg-surface p-6"><div className="font-mono text-[11px] text-action">{number}</div><h3 className="mt-3 text-[15px] font-semibold tracking-tight">{title}</h3><p className="mt-2 text-pretty text-[13px] leading-relaxed text-muted">{text}</p></div>; }
function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-action">{eyebrow}</p><h1 className="mt-2 text-3xl font-bold tracking-tight text-navy">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted">{description}</p></div>{action}</div>; }
function Choice({ title, text, selected }: { title: string; text: string; selected?: boolean }) { return <button className={`rounded-md border p-3 text-left ${selected ? "border-action bg-action/5" : "border-rule hover:bg-ink/5"}`}><span className="flex items-center gap-2 text-xs font-semibold"><span className={`grid size-4 place-items-center rounded-full border ${selected ? "border-action bg-action text-surface" : "border-rule"}`}>{selected && <Check className="size-2.5" />}</span>{title}</span><span className="mt-1 block pl-6 font-mono text-[10px] text-muted">{text}</span></button>; }